-- User settings generated by home-manager (dotfiles.settings) at ~/.config/dotfiles/settings.lua.
-- Missing keys fall back to the defaults below, so this also works before the first switch.

local defaults = {
    apps = {
        terminal    = "ghostty",
        browser     = "firefox",
        fileManager = "nautilus",
        launcher    = "vicinae open",
    },
    input = {
        kbLayout      = "us",
        kbVariant     = "",
        kbOptions     = "",
        naturalScroll = false,
        sensitivity   = 0,
    },
    monitor = {
        scale = 1,
    },
}

local function merge(base, over)
    if type(over) ~= "table" then return base end
    local out = {}
    for k, v in pairs(base) do out[k] = v end
    for k, v in pairs(over) do
        out[k] = (type(v) == "table" and type(base[k]) == "table") and merge(base[k], v) or v
    end
    return out
end

local config_home = os.getenv("XDG_CONFIG_HOME") or ((os.getenv("HOME") or "") .. "/.config")
local chunk = loadfile(config_home .. "/dotfiles/settings.lua")
local ok, user = false, nil
if chunk then ok, user = pcall(chunk) end

return merge(defaults, ok and user or nil)
